"""Transfer the pretrained Kex model from block 4 instead of from the whole network: reset block 5, cut after block 4 with a pooled or a flattened head, and start the flattened head from a ridge regression

Docs: https://franckalbinet.github.io/ossl-fuku-transfer/block4.html.md"""

# AUTOGENERATED! DO NOT EDIT! File to edit: ../nbs/09_block4.ipynb.

# %% auto #0
__all__ = ['CutCNN', 'cut_model', 'reset_top', 'head_inputs', 'ridge_head']

# %% ../nbs/09_block4.ipynb #b0000003
import copy
import numpy as np, torch
from torch.nn import Module, Sequential, Dropout, Linear
from sklearn.linear_model import RidgeCV
from sklearn.preprocessing import StandardScaler
from soilspecdl.all import BatchSNV, TensorSpectrum
from .data import shared_wns
from .transfer import new_model

# %% ../nbs/09_block4.ipynb #b0000008
class CutCNN(Module):
    "The blocks `layers` of a `SpectralCNN`, with a linear head on their pooled or flattened output"
    def __init__(
        self,
        layers, # Conv blocks, such as the first 4 of a `SpectralCNN` backbone
        n_in, # Number of head inputs
        flat=False, # If True, the head reads all channels at all positions; otherwise their average over positions
        dropout=0.4, # Dropout rate before the head
    ):
        super().__init__()
        self.backbone, self.flat = Sequential(*layers), flat
        self.head = Sequential(Dropout(dropout), Linear(n_in, 1))
    def features(self, x):
        "The head's inputs for the spectra `x`"
        x = self.backbone(x)
        return x.flatten(1) if self.flat else x.mean(2)
    def forward(self, x): return self.head(self.features(x)).squeeze(-1)

# %% ../nbs/09_block4.ipynb #b0000010
def cut_model(
    model, # `SpectralCNN`, such as one returned by `pretrain`
    n_blocks=4, # Number of blocks to keep
    flat=False, # Passed to `CutCNN`
)->CutCNN:
    "`CutCNN` with copies of the first `n_blocks` blocks of `model` and a new head"
    layers = copy.deepcopy(list(model.backbone.layers)[:n_blocks])
    with torch.no_grad(): out = Sequential(*layers).eval()(torch.zeros(1, 1, len(shared_wns)))
    return CutCNN(layers, out.shape[1] * (out.shape[2] if flat else 1), flat)

# %% ../nbs/09_block4.ipynb #b0000013
def reset_top(
    model, # `SpectralCNN`, such as one returned by `pretrain`
):
    "Copy of `model` whose last block and head have the random weights of a `new_model`"
    m, fresh = copy.deepcopy(model), new_model()
    m.backbone.layers[-1].load_state_dict(fresh.backbone.layers[-1].state_dict())
    m.head.load_state_dict(fresh.head.state_dict())
    return m

# %% ../nbs/09_block4.ipynb #b0000016
def head_inputs(
    model, # `CutCNN`
    X, # Preprocessed spectra, one per row
    bs=256, # Batch size
)->np.ndarray: # One row per spectrum
    "The head inputs of `model` for the spectra `X`, applying `BatchSNV` first as in training"
    m, snv, out = copy.deepcopy(model).cpu().eval(), BatchSNV(), []
    with torch.no_grad():
        for i in range(0, len(X), bs):
            out.append(m.features(snv(TensorSpectrum(torch.tensor(X[i:i+bs], dtype=torch.float32).unsqueeze(1), wns=shared_wns))).numpy())
    return np.concatenate(out)

def ridge_head(
    model, # `CutCNN`
    X, # Preprocessed training spectra
    y, # Training targets
    alphas=np.logspace(-1, 6, 15), # Ridge penalties to choose from by leave-one-out cross-validation
)->CutCNN:
    "Copy of `model` whose head holds a ridge regression of `y` on its head inputs for `X`"
    m, F = copy.deepcopy(model), head_inputs(model, X)
    sc = StandardScaler().fit(F)
    r = RidgeCV(alphas=alphas).fit(sc.transform(F), y)
    w = r.coef_ / sc.scale_
    with torch.no_grad():
        m.head[-1].weight.copy_(torch.tensor(w[None], dtype=torch.float32))
        m.head[-1].bias.fill_(float(r.intercept_ - (w * sc.mean_).sum()))
    return m
